import { HttpClient } from '@angular/common/http';
import { inject, Injectable, InjectionToken } from '@angular/core';
import { catchError, map, Observable, of, shareReplay } from 'rxjs';
import { CodeSystems } from '../code-systems';
import { CodeOption } from './terminology-client';

/**
 * Where WHO's ICD-10 ↔ ICD-11 mapping tables are served from: public/terminology/, generated by
 * `npm run icd:maps` (scripts/icd-maps/icd-maps.mjs). Static files, loaded only when needed.
 */
export const ICD_MAPS_URL = new InjectionToken<string>('ICD_MAPS_URL', {
  providedIn: 'root',
  factory: () => 'terminology',
});

/** A generated table: code → [mapped code, its title]. */
interface MapTable {
  source: string;
  map: Record<string, [string, string]>;
}

/**
 * WHO's official ICD-10 ↔ ICD-11 mapping ("MapToOneCategory": the one best-matching code in the
 * other classification). Not every code has one: an ICD-11 code may correspond only to a range
 * of ICD-10 codes, and some ICD-10 codes have no ICD-11 counterpart.
 */
@Injectable({ providedIn: 'root' })
export class IcdMaps {
  private readonly http = inject(HttpClient);
  private readonly url = inject(ICD_MAPS_URL);
  private readonly tables = new Map<string, Observable<MapTable['map']>>();

  /** The ICD-11 code WHO's table gives for an ICD-10 code, or null. */
  icd11For(icd10Code: string): Observable<CodeOption | null> {
    return this.lookup('icd10-to-icd11', icd10Code, CodeSystems.icd11);
  }

  /** The ICD-10 code WHO's table gives for an ICD-11 code, or null. */
  icd10For(icd11Code: string): Observable<CodeOption | null> {
    return this.lookup('icd11-to-icd10', icd11Code, CodeSystems.icd10);
  }

  private lookup(table: string, code: string, system: string): Observable<CodeOption | null> {
    return this.table(table).pipe(
      map((entries) => {
        const found = entries[code.trim().toUpperCase()];
        return found ? { system, code: found[0], display: found[1] } : null;
      }),
    );
  }

  /** A table, loaded once and shared. A table that can't be loaded maps nothing. */
  private table(name: string): Observable<MapTable['map']> {
    let table = this.tables.get(name);
    if (!table) {
      table = this.http.get<MapTable>(`${this.url}/${name}.json`).pipe(
        map((loaded) => loaded.map),
        catchError(() => {
          this.tables.delete(name); // try again next time
          return of({});
        }),
        shareReplay(1),
      );
      this.tables.set(name, table);
    }
    return table;
  }
}
